EditorApplication.delayCall+=()=>{try{var rows=new List<string>();foreach(var path in AssetDatabase.FindAssets("t:Mesh",new[]{"Assets/Track/BackyardReverse"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>p.Contains("roger-support")||p.Contains("permanent-water-support")||p.Contains("reverse-trail"))){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);var vs=mesh.vertices;var cs=mesh.colors;var uv=mesh.uv;var uv1=new List<Vector4>();mesh.GetUVs(1,uv1);var triangles=mesh.triangles;var map=new Dictionary<(Vector3Int,Color32,Vector2,Vector4),int>();var v=new List<Vector3>();var c=new List<Color>();var u=new List<Vector2>();var u1=new List<Vector4>();var remap=new int[vs.Length];for(int i=0;i<vs.Length;i++){var color=cs.Length==vs.Length?cs[i]:Color.white;var a=uv.Length==vs.Length?uv[i]:Vector2.zero;var b=uv1.Count==vs.Length?uv1[i]:Vector4.zero;var key=(Vector3Int.RoundToInt(vs[i]*10000),(Color32)color,a,b);if(!map.TryGetValue(key,out int n)){n=v.Count;map[key]=n;v.Add(vs[i]);c.Add(color);u.Add(a);u1.Add(b);}remap[i]=n;}for(int i=0;i<triangles.Length;i++)triangles[i]=remap[triangles[i]];mesh.Clear();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(v);mesh.SetColors(c);mesh.SetUVs(0,u);mesh.SetUVs(1,u1);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);rows.Add(path+": "+vs.Length+" -> "+v.Count+" vertices; unchanged triangles, positions within 0.1mm, same UV seams");}AssetDatabase.SaveAssets();System.IO.File.WriteAllLines("Docs/BackyardReverse/terrain-compaction.txt",rows);}catch(Exception e){System.IO.File.WriteAllText("Docs/BackyardReverse/terrain-compaction-error.txt",e.ToString());}};return "Compact newly authored terrain assets without changing surfaces";
